package net.zartra.gui;
import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.inventory.*;import java.io.*;import java.util.*;
final class GuiService{private final ZartraGUIPlugin plugin;private final MenuManager menus;GuiService(ZartraGUIPlugin p,MenuManager m){plugin=p;menus=m;}private ItemStack b(Material x,String n,String... lore){ItemStack s=new ItemStack(x);org.bukkit.inventory.meta.ItemMeta q=s.getItemMeta();q.setDisplayName(Chat.c(n));if(lore.length>0){List<String> l=new ArrayList<String>();for(String z:lore)l.add(Chat.c(z));q.setLore(l);}s.setItemMeta(q);return s;}void main(Player p){Inventory i=Bukkit.createInventory(new MenuManager.Holder("",false,MenuManager.Screen.MAIN),27,Chat.c("&bZartraGUI"));i.setItem(10,b(Material.CHEST,"&aExisting Menus"));i.setItem(11,b(Material.EMERALD,"&aCreate Menu"));i.setItem(16,b(Material.SLIME_BALL,"&aReload Plugin"));i.setItem(22,b(Material.BARRIER,"&cClose"));p.openInventory(i);}void list(Player p){Inventory i=Bukkit.createInventory(new MenuManager.Holder("",false,MenuManager.Screen.LIST),54,Chat.c("&bMenus"));int n=0;for(MenuDefinition d:menus.all())if(n<45)i.setItem(n++,b(Material.CHEST,"&e"+d.id,"&7Left edit, right preview"));i.setItem(49,b(Material.BOOK,"&7Back"));p.openInventory(i);}void edit(Player p,MenuDefinition d){Inventory i=Bukkit.createInventory(new MenuManager.Holder(d.id,true,MenuManager.Screen.NONE),d.rows*9,Chat.c("&cEditing: "+d.id));for(Map.Entry<Integer,MenuItem>x:d.items.entrySet())i.setItem(x.getKey(),x.getValue().stack());p.openInventory(i);p.sendMessage(Chat.c("&eRight-click an item to edit its persisted actions."));}void actionEditor(Player p,MenuDefinition d,int slot){if(!d.items.containsKey(slot))return;Inventory i=Bukkit.createInventory(new MenuManager.Holder(d.id,false,MenuManager.Screen.ACTIONS,slot),27,Chat.c("&bClick actions"));for(MenuClickType t:MenuClickType.values())i.setItem(t.ordinal(),b(Material.PAPER,"&e"+t.name(),"&7"+d.items.get(slot).actions(t).size()+" actions"));i.setItem(26,b(Material.ARROW,"&7Back"));p.openInventory(i);}void actionList(Player p,MenuDefinition d,int slot,MenuClickType t){List<ActionEntry>a=d.items.get(slot).actions(t);Inventory i=Bukkit.createInventory(new MenuManager.Holder(d.id,false,MenuManager.Screen.ACTION_LIST,slot,t,-1),54,Chat.c("&b"+t.name()+" actions"));for(int n=0;n<a.size()&&n<45;n++){ActionEntry x=a.get(n);i.setItem(n,b(x.enabled?Material.PAPER:Material.REDSTONE,"&e"+(n+1)+". "+x.type,"&7"+x.value,"&7Delay: "+x.delay+" Chance: "+x.chance,"&7Enabled: "+x.enabled+" Stop: "+x.stopOnFailure));}i.setItem(45,b(Material.ARROW,"&7Back"));i.setItem(49,b(Material.EMERALD,"&aAdd action"));p.openInventory(i);}void actionEdit(Player p,MenuDefinition d,int slot,MenuClickType t,int n){ActionEntry a=d.items.get(slot).actions(t).get(n);Inventory i=Bukkit.createInventory(new MenuManager.Holder(d.id,false,MenuManager.Screen.ACTION_EDIT,slot,t,n),27,Chat.c("&bEdit "+a.type));i.setItem(0,b(Material.PAPER,"&eEdit type/value","&7"+a.type+": "+a.value));i.setItem(1,b(a.enabled?Material.EMERALD:Material.REDSTONE,"&eToggle enabled","&7"+a.enabled));i.setItem(2,b(Material.BOOK,"&eDuplicate"));i.setItem(3,b(Material.ARROW,"&eMove up"));i.setItem(4,b(Material.ARROW,"&eMove down"));i.setItem(5,b(Material.WATCH,"&eDelay","&7"+a.delay+" ticks"));i.setItem(6,b(Material.GOLD_NUGGET,"&eChance","&7"+a.chance));i.setItem(7,b(Material.LEVER,"&eStop on failure","&7"+a.stopOnFailure));i.setItem(8,b(Material.SLIME_BALL,"&aTest"));i.setItem(9,b(Material.BARRIER,"&cDelete"));i.setItem(10,b(Material.NETHER_STAR,"&eConditions","&7"+a.conditions.size()+" configured"));i.setItem(26,b(Material.ARROW,"&7Back"));p.openInventory(i);}void conditionList(Player p,MenuDefinition d,int slot,MenuClickType t,int action){ActionEntry a=d.items.get(slot).actions(t).get(action);Inventory i=Bukkit.createInventory(new MenuManager.Holder(d.id,false,MenuManager.Screen.CONDITION_LIST,slot,t,action),54,Chat.c("&bConditions"));for(int n=0;n<a.conditions.size()&&n<45;n++){ConditionEntry c=a.conditions.get(n);i.setItem(n,b(c.enabled?Material.PAPER:Material.REDSTONE,"&e"+(n+1)+". "+c.type.name(),"&7"+c.value,"&7Enabled: "+c.enabled+" Inverted: "+c.inverted));}i.setItem(45,b(Material.ARROW,"&7Back"));i.setItem(48,b(Material.LEVER,"&eMode: "+a.conditionMode));i.setItem(49,b(Material.EMERALD,"&aAdd condition"));p.openInventory(i);}void conditionTypes(Player p,MenuDefinition d,int slot,MenuClickType t,int action){Inventory i=Bukkit.createInventory(new MenuManager.Holder(d.id,false,MenuManager.Screen.CONDITION_TYPES,slot,t,action),27,Chat.c("&bCondition type"));int n=0;for(ConditionEntry.Type type:ConditionEntry.Type.values())if(n<26)i.setItem(n++,b(Material.PAPER,"&e"+type.name(),"&7Click to add"));i.setItem(26,b(Material.ARROW,"&7Back"));p.openInventory(i);}void conditionEdit(Player p,MenuDefinition d,int slot,MenuClickType t,int action,int sub){ConditionEntry c=d.items.get(slot).actions(t).get(action).conditions.get(sub);Inventory i=Bukkit.createInventory(new MenuManager.Holder(d.id,false,MenuManager.Screen.CONDITION_EDIT,slot,t,action,sub),27,Chat.c("&bEdit condition"));i.setItem(0,b(Material.PAPER,"&eEdit value","&7"+c.value));i.setItem(1,b(c.enabled?Material.EMERALD:Material.REDSTONE,"&eToggle enabled","&7"+c.enabled));i.setItem(2,b(Material.LEVER,"&eToggle inversion","&7"+c.inverted));i.setItem(3,b(Material.BOOK,"&eDuplicate"));i.setItem(4,b(Material.ARROW,"&eMove up"));i.setItem(5,b(Material.ARROW,"&eMove down"));i.setItem(6,b(Material.SLIME_BALL,"&aTest"));i.setItem(9,b(Material.BARRIER,"&cDelete"));i.setItem(26,b(Material.ARROW,"&7Back"));p.openInventory(i);}void addCondition(final Player p,final MenuDefinition d,final int slot,final MenuClickType t,final int action,final ConditionEntry.Type type){final ActionEntry a=d.items.get(slot).actions(t).get(action);final ConditionEntry c=new ConditionEntry(type,"");c.order=a.conditions.size();a.conditions.add(c);if(!new ConditionRegistry().get(type).valueRequired){save(p,d);conditionEdit(p,d,slot,t,action,a.conditions.size()-1);return;}ask(p,"&eEnter value for "+type.name(),new ChatInputManager.Callback(){public void run(Player q,String raw){c.value=raw;if(!new ConditionRegistry().valid(c)){a.conditions.remove(c);q.sendMessage(Chat.c("&cInvalid condition value."));conditionTypes(q,d,slot,t,action);return;}save(q,d);conditionEdit(q,d,slot,t,action,a.conditions.size()-1);}});}void editConditionValue(final Player p,final MenuDefinition d,final int slot,final MenuClickType t,final int action,final int sub){ask(p,"&eEnter condition value",new ChatInputManager.Callback(){public void run(Player q,String raw){ConditionEntry c=d.items.get(slot).actions(t).get(action).conditions.get(sub);String old=c.value;c.value=raw;if(!new ConditionRegistry().valid(c)){c.value=old;q.sendMessage(Chat.c("&cInvalid condition value."));}else save(q,d);conditionEdit(q,d,slot,t,action,sub);}});}void deleteConfirm(Player p,MenuDefinition d,int slot,MenuClickType t,int n){Inventory i=Bukkit.createInventory(new MenuManager.Holder(d.id,false,MenuManager.Screen.ACTION_DELETE,slot,t,n),9,Chat.c("&cDelete action?"));i.setItem(3,b(Material.EMERALD,"&aConfirm delete"));i.setItem(5,b(Material.REDSTONE,"&cCancel"));p.openInventory(i);}void add(final Player p,final MenuDefinition d,final int slot,final MenuClickType t){ask(p,"&eEnter TYPE: value",new ChatInputManager.Callback(){public void run(Player q,String raw){MenuAction z=MenuAction.parse(raw);if(z==null||plugin.actions().registry().get(z.type.name())==null){q.sendMessage(Chat.c("&cUnknown action type."));return;}ActionEntry a=new ActionEntry();a.type=z.type.name();a.value=z.value;a.order=d.items.get(slot).actions(t).size();d.items.get(slot).actions(t).add(a);save(q,d);actionList(q,d,slot,t);}});}void editValue(final Player p,final MenuDefinition d,final int slot,final MenuClickType t,final int n){ask(p,"&eEnter TYPE: value",new ChatInputManager.Callback(){public void run(Player q,String raw){MenuAction z=MenuAction.parse(raw);if(z==null||plugin.actions().registry().get(z.type.name())==null){q.sendMessage(Chat.c("&cUnknown action type."));return;}ActionEntry a=d.items.get(slot).actions(t).get(n);a.type=z.type.name();a.value=z.value;save(q,d);actionEdit(q,d,slot,t,n);}});}void number(final Player p,final MenuDefinition d,final int slot,final MenuClickType t,final int n,final boolean chance){ask(p,"&eEnter "+(chance?"chance 0-100":"delay ticks 0-72000"),new ChatInputManager.Callback(){public void run(Player q,String raw){try{ActionEntry a=d.items.get(slot).actions(t).get(n);if(chance){double x=Double.parseDouble(raw);if(!ActionValidator.chance(x))throw new NumberFormatException();a.chance=x;}else{long x=Long.parseLong(raw);if(!ActionValidator.delay(x))throw new NumberFormatException();a.delay=x;}save(q,d);actionEdit(q,d,slot,t,n);}catch(NumberFormatException e){q.sendMessage(Chat.c("&cInvalid number."));}}});}private void ask(Player p,String prompt,ChatInputManager.Callback c){plugin.inputs().begin(p,c);p.closeInventory();p.sendMessage(Chat.c(prompt+" &7(type cancel to abort)"));}void save(Player p,MenuDefinition d){try{menus.save(d);}catch(IOException e){plugin.getLogger().warning("Unable to save "+d.id+": "+e.getMessage());p.sendMessage(Chat.c("&cSave failed; see console."));}}void saveEditor(Inventory inv){if(!(inv.getHolder() instanceof MenuManager.Holder))return;MenuManager.Holder h=(MenuManager.Holder)inv.getHolder();if(!h.edit)return;MenuDefinition d=menus.get(h.id);if(d==null)return;Map<Integer,MenuItem>old=new HashMap<Integer,MenuItem>(d.items);d.items.clear();for(int slot=0;slot<inv.getSize();slot++){ItemStack s=inv.getItem(slot);if(s!=null&&s.getType()!=Material.AIR){MenuItem prior=old.get(slot),x=new MenuItem(s,null);if(prior!=null){x.cooldown=prior.cooldown;for(MenuClickType t:MenuClickType.values())for(ActionEntry a:prior.actions(t))x.actions(t).add(a.copy());}d.items.put(slot,x);}}try{menus.save(d);}catch(IOException e){plugin.getLogger().warning("Unable to save "+d.id+": "+e.getMessage());}}
}